{
  "name": "opencode-pr-signature",
  "version": "1.2.2",
  "type": "module",
  "description": "OpenCode plugin for automatically adding AI model signature to commits, Pull Requests, and Issues",
  "author": "arttttt <artembambalov1993@gmail.com>",
  "license": "Apache-2.0",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/arttttt/opencode-pr-signature.git"
  },
  "keywords": [
    "opencode",
    "plugin",
    "github",
    "pull-request",
    "issue",
    "signature",
    "ai"
  ],
  "main": "src/entry/legacy.ts",
  "exports": {
    ".": "./src/entry/legacy.ts",
    "./server": "./src/entry/server.ts"
  },
  "files": [
    "src",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "test": "bun test",
    "typecheck": "tsc --noEmit"
  },
  "dependencies": {
    "@opencode-ai/plugin": "^1.0.143",
    "@opencode-ai/sdk": "^1.0.143"
  },
  "devDependencies": {
    "@types/bun": "latest",
    "bun": "^1.2.0",
    "@types/node": "^22.0.0",
    "typescript": "~5.9.3"
  },
  "engines": {
    "bun": ">=1.0.0"
  }
}
